tool.command:
@PREPARE_ENV@ @PREPARE_CORPUS@ @PREPARE_DICTIONARY@ @PREPARE_ACOUSTIC@
## 4. Run Train Dictionary ## Syntax: mfa train_dictionary [OPTIONS] CORPUS_DIRECTORY DICTIONARY_PATH ACOUSTIC_MODEL_PATH OUTPUT_DIRECTORY mfa train_dictionary corpus_dir $dict_arg $ac_arg output_dir --job_name 'mfa_train_dict_job' #if str($silence_probabilities) == "true": --silence_probabilities #end if
## 5. Move Result ## The new dictionary (with probabilities) is saved in the output_dir. ## We pick the first .dict or .txt file MFA produced. && mv "\$(find output_dir -maxdepth 1 -type f \( -name '*.dict' -o -name '*.txt' \) | head -1)" '$output_dictionary'
